CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE methodology_release (id TEXT PRIMARY KEY, scoring_enabled BOOLEAN NOT NULL DEFAULT FALSE CHECK (scoring_enabled = FALSE), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO methodology_release(id) VALUES ('GULGO_PASS_V1_PILOT');
CREATE TABLE app_user (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), external_auth_id TEXT NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE economic_subject (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), kind TEXT NOT NULL CHECK(kind IN ('individual','organization')), display_name TEXT NOT NULL);
CREATE TABLE subject_representation (subject_id UUID NOT NULL REFERENCES economic_subject(id), user_id UUID NOT NULL REFERENCES app_user(id), role TEXT NOT NULL CHECK(role IN ('owner','representative')), valid_from DATE NOT NULL, valid_until DATE, PRIMARY KEY(subject_id,user_id), CHECK(valid_until IS NULL OR valid_until>=valid_from));
CREATE TABLE pass_dossier (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), subject_id UUID NOT NULL REFERENCES economic_subject(id), methodology_id TEXT NOT NULL REFERENCES methodology_release(id), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','under_review','pending_approval','closed','cancelled')), observation_start DATE, observation_end DATE, revision INT NOT NULL DEFAULT 1 CHECK(revision>0), CHECK(observation_start IS NULL OR observation_end IS NULL OR observation_end>=observation_start));
CREATE TABLE indicator_definition (methodology_id TEXT NOT NULL REFERENCES methodology_release(id), code TEXT NOT NULL, dimension_code TEXT NOT NULL CHECK(dimension_code IN ('D1','D2','D3','D4','D5','D6')), label TEXT NOT NULL, PRIMARY KEY(methodology_id,code));
CREATE TABLE variable_definition (methodology_id TEXT NOT NULL REFERENCES methodology_release(id), code TEXT NOT NULL, label TEXT NOT NULL, value_type TEXT NOT NULL CHECK(value_type IN ('text','number','date','boolean','enum','json')), critical BOOLEAN NOT NULL DEFAULT FALSE, PRIMARY KEY(methodology_id,code));
CREATE TABLE indicator_variable (methodology_id TEXT NOT NULL, indicator_code TEXT NOT NULL, variable_code TEXT NOT NULL, PRIMARY KEY(methodology_id,indicator_code,variable_code), FOREIGN KEY(methodology_id,indicator_code) REFERENCES indicator_definition(methodology_id,code), FOREIGN KEY(methodology_id,variable_code) REFERENCES variable_definition(methodology_id,code));
CREATE TABLE variable_observation (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), dossier_id UUID NOT NULL REFERENCES pass_dossier(id), methodology_id TEXT NOT NULL, variable_code TEXT NOT NULL, value_json JSONB, data_status TEXT NOT NULL CHECK(data_status IN ('available','missing','refused','temporarily_unavailable','under_verification')), period_start DATE, period_end DATE, source_type TEXT, recorded_by UUID NOT NULL REFERENCES app_user(id), recorded_at TIMESTAMPTZ NOT NULL DEFAULT now(), supersedes_id UUID REFERENCES variable_observation(id), FOREIGN KEY(methodology_id,variable_code) REFERENCES variable_definition(methodology_id,code), CHECK(period_start IS NULL OR period_end IS NULL OR period_end>=period_start), CHECK((data_status='available' AND value_json IS NOT NULL) OR (data_status<>'available' AND value_json IS NULL)));
CREATE TABLE evidence (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), dossier_id UUID NOT NULL REFERENCES pass_dossier(id), storage_key TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL CHECK(sha256 ~ '^[a-f0-9]{64}$'), mime_type TEXT NOT NULL, uploaded_by UUID NOT NULL REFERENCES app_user(id), uploaded_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(id,dossier_id));
ALTER TABLE variable_observation ADD CONSTRAINT uq_observation_dossier UNIQUE(id,dossier_id);
CREATE TABLE evidence_link (dossier_id UUID NOT NULL REFERENCES pass_dossier(id), evidence_id UUID NOT NULL, observation_id UUID NOT NULL, relationship TEXT NOT NULL, PRIMARY KEY(evidence_id,observation_id), FOREIGN KEY(evidence_id,dossier_id) REFERENCES evidence(id,dossier_id), FOREIGN KEY(observation_id,dossier_id) REFERENCES variable_observation(id,dossier_id));
CREATE TABLE evidence_assessment (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), observation_id UUID NOT NULL REFERENCES variable_observation(id), level TEXT NOT NULL CHECK(level IN ('N1','N2','N3','N4')), rationale TEXT NOT NULL, assessed_by UUID NOT NULL REFERENCES app_user(id), assessed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE control_finding (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), dossier_id UUID NOT NULL REFERENCES pass_dossier(id), code TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('open','reviewing','resolved','accepted_with_reservation')), severity TEXT NOT NULL CHECK(severity IN ('info','warning','blocking')), rationale TEXT, resolved_by UUID REFERENCES app_user(id));
CREATE TABLE applicability_decision (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), dossier_id UUID NOT NULL REFERENCES pass_dossier(id), methodology_id TEXT NOT NULL, indicator_code TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('applicable','adapted','not_applicable','not_evaluable')), rationale TEXT NOT NULL, decided_by UUID NOT NULL REFERENCES app_user(id), decided_at TIMESTAMPTZ NOT NULL DEFAULT now(), FOREIGN KEY(methodology_id,indicator_code) REFERENCES indicator_definition(methodology_id,code));
CREATE TABLE assessment_run (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), dossier_id UUID NOT NULL REFERENCES pass_dossier(id), methodology_id TEXT NOT NULL REFERENCES methodology_release(id), mode TEXT NOT NULL DEFAULT 'descriptive' CHECK(mode='descriptive'), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE assessment_result (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), run_id UUID NOT NULL REFERENCES assessment_run(id), indicator_code TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('calculated','descriptive_only','not_calculable','not_applicable','under_review')), numeric_value NUMERIC, reason_code TEXT, source_observation_ids UUID[] NOT NULL DEFAULT '{}');
CREATE TABLE audit_event (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), actor_id UUID REFERENCES app_user(id), object_type TEXT NOT NULL, object_id UUID NOT NULL, action TEXT NOT NULL, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), detail JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX idx_dossier_subject ON pass_dossier(subject_id);
CREATE INDEX idx_observation_dossier ON variable_observation(dossier_id,variable_code);
CREATE INDEX idx_finding_dossier ON control_finding(dossier_id,status);
-- Access control, immutable release enforcement and audit triggers must be installed before production.
